import{_ as r,o as e,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const _=JSON.parse('{"title":"容器隔離與配額機制 (Architecture & Security)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":null}'),o={name:"architecture.md"};function c(l,t,n,s,u,h){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="容器隔離與配額機制-architecture-security" tabindex="-1">容器隔離與配額機制 (Architecture &amp; Security) <a class="header-anchor" href="#容器隔離與配額機制-architecture-security" aria-label="Permalink to &quot;容器隔離與配額機制 (Architecture &amp; Security)&quot;">​</a></h1><p>Craft-Core Hosting 採用高安全性的容器隔離架構，確保每個用戶應用運行在獨立的 Docker 容器內，資源互不影響。</p><hr><h2 id="資源隔離與限制" tabindex="-1">資源隔離與限制 <a class="header-anchor" href="#資源隔離與限制" aria-label="Permalink to &quot;資源隔離與限制&quot;">​</a></h2><p>系統對每一個容器實施 CPU 與記憶體硬性邊界限制：</p><ul><li><strong>CPU 配額限制</strong>：根據設定的 CPU 比例限制算力資源（最高 100% CPU）。</li><li><strong>記憶體限額限制</strong>：當容器記憶體使用超過分配上限時（例如 512MB），系統會防止進程干擾其他應用。</li><li><strong>SSD 磁碟限制</strong>：每台容器擁有獨立受控之硬碟寫入配額。</li></ul><hr><h2 id="網路與反向代理" tabindex="-1">網路與反向代理 <a class="header-anchor" href="#網路與反向代理" aria-label="Permalink to &quot;網路與反向代理&quot;">​</a></h2><ul><li><strong>內部隔離</strong>：容器內部預設無法直接暴露公開 Port，維護安全隔離。</li><li><strong>8 位專屬域名與 SSL 自動加密</strong>：一鍵開啟對外 Port 後，系統會為容器自動核發 8 位英數隨機專屬域名 (例: <code>app-a8k2m9x1.hosting.craft-core.xyz</code>)，並由 Caddy 提供 HTTPS SSL 安全加密存取。</li></ul>',9)])])}const p=r(o,[["render",c]]);export{_ as __pageData,p as default};
